fn main() {
    println!(
        "// @generated by `cargo run -p rintawa-memory --example extraction_schemas`; do not edit."
    );
    for (name, schema) in [
        ("STATE", rintawa_memory::extraction::state_schema()),
        ("RECORD", rintawa_memory::extraction::record_schema()),
        ("COMMAND", rintawa_memory::extraction::command_schema()),
        ("PROCESS", rintawa_memory::extraction::process_schema()),
    ] {
        println!("pub const {name}: &str = {:?};", schema.to_string());
    }
}
